using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Net;using System.Text;using System.Text.RegularExpressions;using System.Threading;using System.Web.Script.Serialization;
namespace PZ3D {
 sealed class FeedbackReceipt {public string id,receivedUtc,status="received";}
 sealed class FeedbackHistory {public int schema=1;public List<FeedbackReceipt> history=new List<FeedbackReceipt>();}
 // Collection, review and submission are separate. Only a confirmed immutable
 // preview can reach the fixed first-party endpoint.
 sealed class FeedbackService:IDisposable {
  internal const string Endpoint="https://orangezl.com/api/feedback";
  const int TailBytes=32768,MaximumBody=262144;
  readonly Engine engine;readonly object gate=new object();readonly Func<byte[],Dictionary<string,object>> transport;readonly Func<Dictionary<string,object>> hardware;readonly Func<DateTime> clock;readonly CancellationTokenSource cancel=new CancellationTokenSource();
  readonly JavaScriptSerializer json=new JavaScriptSerializer{MaxJsonLength=1048576,RecursionLimit=16};
  Prepared preview;bool sending,disposed;
  sealed class Prepared {internal string Token,Id;internal DateTime Created;internal byte[] Body;internal object View;internal FeedbackReceipt Receipt;}
  internal FeedbackService(Engine engine,Func<byte[],Dictionary<string,object>> transport=null,Func<Dictionary<string,object>> hardware=null,Func<DateTime> clock=null){this.engine=engine;this.transport=transport??Upload;this.hardware=hardware??SystemInfo;this.clock=clock??(()=>DateTime.UtcNow);}
  internal static bool Action(string action){return action=="feedbackStatus"||action=="feedbackPreview"||action=="feedbackSend";}
  internal static void Validate(string action,Dictionary<string,object> p){
   if(p==null)throw new InvalidOperationException("反馈参数无效。");object v;
   if(action=="feedbackStatus"){if(p.Count!=0)throw new InvalidOperationException("反馈记录不接受采集参数。");return;}
   if(action=="feedbackSend"){if(p.Count!=2||!p.TryGetValue("token",out v)||!(v is string)||!Regex.IsMatch((string)v,@"\A[a-f0-9]{32}\z")||!p.TryGetValue("confirmed",out v)||!(v is bool)||(bool)v!=true)throw new InvalidOperationException("请预览内容并勾选同意发送。");return;}
   if(action!="feedbackPreview"||p.Count!=4||!p.TryGetValue("description",out v)||!(v is string)||string.IsNullOrWhiteSpace((string)v)||((string)v).Length>2000)throw new InvalidOperationException("请填写问题描述，最多 2000 字。");
   foreach(string k in new[]{"gameLog","launcherLog","system"})if(!p.TryGetValue(k,out v)||!(v is bool))throw new InvalidOperationException("请选择要发送的资料。");
  }
  string HistoryPath{get{return Path.Combine(engine.Data,"feedback","history.json");}}
  FeedbackHistory History(){var h=LauncherNativeState.Read(HistoryPath,()=>new FeedbackHistory());if(h==null||h.schema!=1||h.history==null||h.history.Count>20||h.history.Any(x=>x==null||!Id(x.id)||x.status!="received"||!ValidDate(x.receivedUtc)))throw new IOException("反馈发送记录无法读取。");return h;}
  static bool Id(string value){return Regex.IsMatch(value??"",@"\A[a-f0-9]{32}\z");}
  static bool ValidDate(string text){DateTimeOffset parsed;return text!=null&&text.Length<=64&&DateTimeOffset.TryParse(text,out parsed);}
  bool Available(string file){try{LauncherMaintenance.NoReparse(file);return File.Exists(file);}catch{return false;}}
  internal object Status(){lock(gate){return new{history=History().history.ToArray(),available=new{gameLog=Available(Path.Combine(engine.User,"console.txt")),launcherLog=Available(Path.Combine(engine.Data,"diagnostics","launcher.log"))},endpoint=Endpoint};}}
  static string Clean(string text){var result=new StringBuilder();using(var reader=new StringReader(text??"")){string line;bool chat=false;while((line=reader.ReadLine())!=null){bool header=Regex.IsMatch(line,@"^\s*(?:(?:LOG|WARN|ERROR|DEBUG)\s*:|[0-9]{4}-[0-9]{2}-[0-9]{2}T)",RegexOptions.IgnoreCase|RegexOptions.CultureInvariant,TimeSpan.FromMilliseconds(100));if(Regex.IsMatch(line,@"(?i)\bchatmessage\b|\bchat message\b|\bwhisper\b|(?:^|[\s:>])chat\s*[:>]",RegexOptions.CultureInvariant,TimeSpan.FromMilliseconds(100))){chat=true;line="[聊天内容已隐藏]";}else if(chat&&!header)line="[聊天内容已隐藏]";else{if(header)chat=false;line=GameLogAnalyzer.Sanitize(line);}foreach(string identity in new[]{Environment.UserName,Environment.MachineName})if(!string.IsNullOrEmpty(identity))line=Regex.Replace(line,Regex.Escape(identity),"[已隐藏]",RegexOptions.IgnoreCase|RegexOptions.CultureInvariant,TimeSpan.FromMilliseconds(100));result.Append(line).Append('\n');if(result.Length>60000)break;}}return result.ToString().Substring(0,Math.Min(result.Length,65536));}
  string ReadTail(string file){LauncherMaintenance.NoReparse(file);using(var input=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete)){GameDiagnostics.VerifyHandle(input,file);long start=Math.Max(0,input.Length-TailBytes);input.Seek(start,SeekOrigin.Begin);byte[] bytes=new byte[Math.Min(TailBytes,(int)Math.Min(input.Length,int.MaxValue))];int total=0,n;while(total<bytes.Length&&(n=input.Read(bytes,total,bytes.Length-total))>0)total+=n;string text=Encoding.UTF8.GetString(bytes,0,total);if(start>0){int line=text.IndexOf('\n');text=line<0?"":text.Substring(line+1);}return Clean(text);}}
  internal object Preview(Dictionary<string,object> p){Validate("feedbackPreview",p);lock(gate){if(disposed)throw new ObjectDisposedException("FeedbackService");if(sending)throw new InvalidOperationException("反馈正在发送，请稍候。");var files=new List<Dictionary<string,object>>();var categories=new List<string>();foreach(string category in new[]{"gameLog","launcherLog"})if((bool)p[category]){string name=category=="gameLog"?"console.txt":"launcher.log",file=category=="gameLog"?Path.Combine(engine.User,name):Path.Combine(engine.Data,"diagnostics",name);string text;try{text=ReadTail(file);}catch{throw new IOException("无法读取"+(category=="gameLog"?"游戏日志":"启动器日志")+"，请取消该项后重试。");}categories.Add(category);files.Add(new Dictionary<string,object>{{"name",name},{"text",text}});}
    Dictionary<string,object> system=null;if((bool)p["system"]){categories.Add("system");system=hardware();ValidateSystem(system);}
    string id=Guid.NewGuid().ToString("N"),token=Guid.NewGuid().ToString("N"),description=Clean((string)p["description"]).Trim();if(description.Length>2000)description=description.Substring(0,2000);if(description.Length==0)throw new InvalidOperationException("请填写问题描述。");DateTime created=clock().ToUniversalTime();string version=AppVersion.Current;
    var wire=new{schema=1,requestId=id,createdUtc=created.ToString("o"),appVersion=version,description=description,categories=categories.ToArray(),files=files.ToArray(),system=system};byte[] body=Encoding.UTF8.GetBytes(json.Serialize(wire));if(body.Length>MaximumBody)throw new InvalidOperationException("所选资料过大，请减少勾选后重试。");
    var view=new{token=token,id=id,createdUtc=created.ToString("o"),description=description,categories=categories.ToArray(),files=files.Select(f=>new{name=(string)f["name"],text=(string)f["text"],bytes=Encoding.UTF8.GetByteCount((string)f["text"])}).ToArray(),system=system,bytes=body.Length};preview=new Prepared{Id=id,Token=token,Created=created,Body=body,View=view};return view;
  }}
  internal object Send(Dictionary<string,object> p){Validate("feedbackSend",p);Prepared selected;lock(gate){if(disposed)throw new ObjectDisposedException("FeedbackService");selected=preview;if(selected==null||selected.Token!=(string)p["token"]||clock().ToUniversalTime()-selected.Created>TimeSpan.FromMinutes(10))throw new InvalidOperationException("预览已失效，请重新预览并确认。");if(selected.Receipt!=null)return new{id=selected.Receipt.id,receivedUtc=selected.Receipt.receivedUtc,status="received",message="反馈已发送"};if(sending)throw new InvalidOperationException("反馈正在发送，请稍候。");sending=true;}
   try{var response=transport(selected.Body);object id,at,status;if(response==null||response.Count!=3||!response.TryGetValue("id",out id)||!(id is string)||(string)id!=selected.Id||!response.TryGetValue("receivedUtc",out at)||!(at is string)||!ValidDate((string)at)||!response.TryGetValue("status",out status)||!Equals(status,"received"))throw new IOException("服务器未返回有效回执，请重试。");var receipt=new FeedbackReceipt{id=(string)id,receivedUtc=(string)at};LauncherNativeState.Locked(HistoryPath,()=>{var history=History();history.history.RemoveAll(x=>x.id==receipt.id);history.history.Insert(0,receipt);history.history=history.history.Take(20).ToList();LauncherNativeState.Write(HistoryPath,history);return true;});lock(gate)selected.Receipt=receipt;return new{id=receipt.id,receivedUtc=receipt.receivedUtc,status="received",message="反馈已发送"};}
   finally{lock(gate)sending=false;}
  }
  static void ValidateSystem(Dictionary<string,object> value){string[] keys={"os","architecture","cpu","logicalProcessors","totalMemoryGiB","gpu","vramGiB","driver"};if(value==null||value.Count!=keys.Length||keys.Any(k=>!value.ContainsKey(k)))throw new IOException("电脑信息读取失败。");}
  Dictionary<string,object> SystemInfo(){var h=engine.TestMode?HardwareProbe.Unknown():HardwareProbe.Cached();return new Dictionary<string,object>{{"os",Environment.OSVersion.VersionString},{"architecture",Environment.Is64BitOperatingSystem?"X64":"X86"},{"cpu",SafeHardware(Environment.GetEnvironmentVariable("PROCESSOR_IDENTIFIER"),256)},{"logicalProcessors",Environment.ProcessorCount},{"totalMemoryGiB",h.totalMemoryGiB},{"gpu",SafeHardware(h.gpu,256)},{"vramGiB",h.vramGiB},{"driver",SafeHardware(h.driver,128)}};}
  static string SafeHardware(string value,int length){value=GameLogAnalyzer.Sanitize(value??"");return value.Substring(0,Math.Min(value.Length,length));}
  Dictionary<string,object> Upload(byte[] body){if(engine.TestMode)throw new InvalidOperationException("测试模式不发送真实反馈。");var request=(HttpWebRequest)WebRequest.Create(Endpoint);request.Method="POST";request.ContentType="application/json; charset=utf-8";request.Accept="application/json";request.ContentLength=body.Length;request.UserAgent="OrangeLauncher/"+AppVersion.Current;return FeedbackUpload.Send(request,body,cancel.Token,15000);}
  public void Dispose(){lock(gate){if(disposed)return;disposed=true;cancel.Cancel();preview=null;}cancel.Dispose();}
 }
}
